"""Metadata and static-source design only: no numpy, grid or search generation."""
import time
START=time.perf_counter()
import ast,datetime,hashlib,json,sys
from pathlib import Path
G=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(Path(p).read_text())
def save(p,x):
    with Path(p).open('x') as f:json.dump(x,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')

def run(root):
    root=Path(root);d=root/'stage488';assert not d.exists();d.mkdir(mode=0o700)
    old=read(root/'stage485/plan-private.json')
    for group in ('sources','protected','original408_preserve'):
        for p,h in old[group].items():assert sha(p)==h,p
    assert sha(old['ledger_path'])==old['ledger_sha256']
    snapshot=Path('/tmp/haic-retry-stage485-private/native/D485-A/initial-full-private.json')
    baseline=snapshot.with_name('unsupported-geometry-private.json');saved=read(baseline)
    N=len(saved['center']);obstacles=len(saved['free_clearance']);assert N==321 and obstacles==6
    source_paths=[G/p for p in ('retry/racing258_plan.py','retry/executor397.py','retry/paired417_common.py','retry/signed417_executor.py','retry/pace269_run.py','core/finish_line.py')]
    trees={str(p.relative_to(G)):ast.parse(p.read_text()) for p in source_paths}
    funcs={node.name:node for node in trees['retry/racing258_plan.py'].body if isinstance(node,ast.FunctionDef)}
    assert {'geometry','basis','curvature','obstacle_clearance','profile','solve'}<=set(funcs)
    assert '.nodes' in (G/'retry/executor397.py').read_text() and 'FINISH_CONFIRM' in (G/'retry/executor397.py').read_text()
    local_counts=lambda n:dict(stations=n,offsets_per_station_max=21,unique_point_candidates_max=n*21,pair_states_max=n*21**2,edge_predicates_max=n*21**2,edge_obstacle_distance_pairs_max=n*21**2*6,curvature_triples_max=n*21**3,parent_bytes_uint8_max=n*21**2,packed_curvature_bits_bytes_max=(n*21**3+7)//8)
    contract=dict(stage=488,status='DESIGN_ONLY_NO_SEARCH_OR_CONSTRUCTION_AUTHORIZED',deadline_utc='2026-10-20T10:01:55Z',automatic_extension=False,
      purpose='One independent centerline-normal lattice method family: can it produce one geometry-qualified reference candidate on the already exposed first485 map? No time optimization or new condition. Multiple representation/search changes are intentional, not a one-factor causal claim.',
      phase=dict(new_search=0,new_optimization=0,new_grid_states=0,new_candidate_paths=0,new_geometry_draws=0,new_profiles=0,new_actual=0,new_resets=0,new_worlds=0,new_ticks=0,new_seed=0),
      input=dict(snapshot_sha256=sha(snapshot),baseline_sha256=sha(baseline),stored_stations=N,stored_obstacles=obstacles,split='Already exposed first485 DEV; identity/history unchanged. No independent-DEV count.',second_condition_used=False,missing_input='Technical stop. Never reset, rematerialize, replace or choose another condition.'),
      representation=dict(stations='Original geometry(snapshot) center_i/normal_i in source road-index order; do not optimize/reorder/add stations.',q_resolution_m=.5,q_values_order='0,+0.5,-0.5,+1,-1,...,+4.5,-4.5,+B,-B; B is exact frozen float result of40/6-1.4-0.35.',max_q=21,source_arc='Original centerline basis() arc_s and L=sum(centerline edge lengths), used only as fixed taper labels. Not arc length of the new path.',source_taper='tau_i is original sampled smoothstep(min(min(s_i,L-s_i)/10,1)). No B16 coefficient vector is required.',point='Serialize float64 p_i(q)=c_i+n_i*(tau_i*q), then deduplicate by actual full point float64 bits; first canonical rank wins. p0,p1,p_last are copied directly from original serialized center bytes, not recomputed c+n*0; discard aliases there.',seam='Output M=N distinct station entries, no appended duplicate closure point. The closing edge is p_last to p0 and its source-arc labels are s_last to L.',postprocess='None: no smoothing, resampling, decimation, waypoint shortcut or serialization rounding after certification. Every consumed geometry byte must match the certified final polyline.'),
      offset_certificate=dict(source_gate='Unchanged station scalar-offset bound B, obstacle inflation and aggregate source free_feasible acceptance. The new continuous tube certificate is an explicitly stronger construction requirement.',reference_taper='Analytic smoothstep tau_ref(s) with frozen source float64 s_i,L treated as exact rational constants, on unwrapped [0,L]. It is unimodal, so its minimum on each edge label interval is min(endpoint values), including across midlap.',exact_arithmetic='Use Fraction.from_float for B, each c coordinate, each serialized p coordinate, s_i and L. Form u=Fraction(p)-Fraction(c); NEVER Fraction(p-c) after a rounded float subtraction. Square/sum exactly; do not assume stored normal has exact unit norm.',edge_rule='Let tmin_i=min(tau_ref(s_i),tau_ref(s_{i+1})), with s_N=L. Require ||u_i||² and ||u_{i+1}||² <= (B*tmin_i)². Precompute node eligibility using the smaller bound from both incident edges.',proof='For actual straight segment P(t) and center chord C(t), P-C=(1-t)u_i+t*u_next. Convexity of norm gives ||P-C||<=B*tmin_i<=B*tau_ref(s). This is a Euclidean tube bound, not an offset times rotating-normal identity or actual road-body containment.',boundary='tau_ref(0)=tau_ref(L)=0 forces p1 and p_last onto their center bytes, as well as p0. This conservative sufficient rule removes a free first-successor root index and simplifies the closed-cycle DP.',rounding='Any exact-certificate failure removes that node/edge; no epsilon correction or tolerance relaxation. Sampled and analytic taper rounding differences are not silently equated.'),
      graph=dict(states='Layer i stores ordered pair (rank at i-1,rank at i); exact pair geometry carries incoming heading. No angle quantization or one-side initial homotopy.',initial='Single pair (p0=center0,p1=center1), validated first edge. If source arc order/schema is invalid, stop technical.',transition='For each layer i=2..N-1 and eligible a,b,c: require complete edge p_(i-1)^b to p_i^c valid and original three-point curvature at p_(i-1)^b within target. Reachable (a,b) may enter (b,c). Both normal-offset signs remain available.',edge_predicate='Positive finite edge length; closest point over the ENTIRE edge against ALL six physical obstacles using original radius+2.9+0.25; source clearance>=0 for this sufficient subgraph; continuous offset certificate above. No endpoint-only shortcut.',triple_predicate='Original curvature() expression 2cross/max(norm(a)*norm(b)*norm(a+b),1e-9), exact source float64 operation order, abs(kappa)<=tan(0.4)/3.24. Additionally require incoming_edge dot outgoing_edge>0 with no epsilon, preventing collinear reversals hidden by the curvature denominator floor. These are strict sufficient construction predicates; not a claim of exhausting the looser original aggregate-tolerance gate.',finish='After reaching N-1, validate closing edge, triple (p_(N-2),p_last,p0) and seam triple (p_last,p0,p1). Apply the same complete triple predicate, including positive dot, to last and root vertices. All N curvature vertices and N edges are certified.',search='One layered reachability DP, not Dijkstra/time optimization. No score or estimated lap time. Store lowest canonical predecessor rank for each reachable pair.',ties='Station order then q canonical rank. Within a target pair choose smallest predecessor rank; at finish choose lexicographically smallest terminal pair with both seam checks. Reconstruct exactly one path, no other-goal retry.',finite_completeness='Completed DP exhausts only the registered conservative local-predicate graph. Pair merging is valid for these local constraints and fixed boundary points. It does not prove continuous/physical infeasibility or completeness for nonlocal executor restrictions.'),
      independent_gate=dict(implementation='Separate source checker, not the search predicates or cached feasibility flags. Independently reconstruct center/normals/source arc; authenticate snapshot and every final point/offset/rank and byte hash.',source_functions='Pin original geometry(), obstacle_clearance(), curvature(), B/taper definitions. Candidate offset array replaces B16 offset output while retaining the same numerical source free_feasible formula.',final_original_acceptance='Recompute all six full-polyline segment clearances, all N source curvature values including seam, all station offset residuals and V=sum(negative_clearance²)+100*sum(curvature_excess²)+sum(offset_excess²). Require minclear>=-1e-6 and V<=1e-8, unchanged. Also require the stronger registered continuous tube certificate.',evidence='Audit node eligibility, edge masks, packed triple masks, layer reachability/predecessors and final closed-route certificate. An independent source algebra audit recomputes predicates; it does not select a second route.',interpolation='The final representation IS these straight edges; every edge is checked continuously for obstacles and tube offset, every corner for the original three-point curvature proxy. Polyline corners do not have finite classical C2 curvature. No stronger continuous steering/dynamic certificate is claimed.',future_changes='Any later interpolation/rounding/resampling/smoothing creates a new artifact and invalidates this certificate until every final edge/corner/offset/seam is independently recertified under a separately registered method. No silent postprocessing.'),
      executor_boundary=dict(source_inspection='Existing executor consumes line(M,2), ds(M), speed(M+1), model; it does not consume B16 coefficients. Lattice polyline is representable, but this search produces geometry only.',schema='Finite exact line bytes, ds>0, no duplicated closure vertex; closed seam and start/finish point fixed. Any later ds/kappa/speed/pace/P4 must be rebuilt from this exact final line, never borrowed from485.',compatibility_check='Inspect final polyline for duplicate points, adjacent backtracking and nonadjacent intersections/overlaps and on-reference canonical projection ambiguity. Existing cursor window and off-reference nearest projections remain unqualified; no all-pose tracking guarantee.',nonlocal_limit='A first returned goal failing nonlocal compatibility does not prove the graph has no compatible path: earlier prefix merging can lose alternatives. Stop without another goal or state enrichment.',not_part_of_this_test=['No speed profile or estimated time objective','No P4/SourceC act/native/model source witness','No pixel/whole-lap/controller/ranking comparison'],promotion='Geometry-qualified candidate with explicit compatibility result only. Complete executor input, speed law and native/source fidelity remain separate future gates, not automatic follow-up.'),
      counts_observed_map=local_counts(N),counts_hard=local_counts(512),
      hard_caps=dict(search_invocations=1,max_stations=512,max_unique_points_per_station=21,max_reconstructed_paths=1,producer_node_checks=512*21,producer_edge_checks=512*21**2,producer_triple_checks=512*21**3,independent_audit_node_checks=512*21,independent_audit_edge_checks=512*21**2,independent_audit_triple_checks=512*21**3,max_source_full_path_checks=1,max_nonadjacent_segment_pairs=512*511//2,whole_CPU_s=60,whole_wall_s=90,max_RSS_bytes=256*1024**2,total_retained_bytes=16*1024**2,max_files=40,max_file_bytes=2*1024**2,max_temporary_bytes=2*1024**2,termination_files_reserved_inside_cap=2,termination_bytes_reserved_inside_cap=65536,free_reserve_each_volume_bytes=512*1024**2,required_preflight_each_volume_bytes=530*1024**2,actual=0,resets=0,worlds=0,ticks=0,seed_draws=0,profiles=0,solver_optimizations=0,paid_resources=0,research_remaining=26175,reserve=84000,reserve_used=0),
      resources='Limits cover imports, static/source/input checks, rational certificates, dedup, all graph predicates and DP, one reconstruction, independent source audit, compatibility check, serialization and full readbacks. Charge work before each batch. Stream K^3 predicates per layer; do not materialize N*K^3 float arrays. 60/90 is a hard cap, not a benchmark or completion guarantee.',
      records='Retain q/point/dedup and rational-certificate witnesses privately; full edge-min-clearance masks and hashes, packed triple-valid bits, every layer reachability/predecessor table and work counts; selected path and full final certificate. Split arrays into bounded files with declared shapes/dtypes/padding. Source audit can reconstruct all predicates. All files+code+publication+temp use one global quota with pre-reserved companion artifacts/termination capacity; no old raw copy or deletion.',
      prerequisites=['Explicit later authorization;488 is static design only. Register exact implementation, source/runtime and inputs before any grid generation.', 'Zero-search fixtures: both bypass signs, interior segment collision, curvature requiring incoming edge, duplicate/bit signed-zero handling, taper rounding and midpoint fold, closing edge/last/root curvature, predecessor ties and nonlocal-compatibility limits.', 'Verify full frozen first485 input present, current deadline/protected/main/Participants/backup pins, fresh CPU/RSS/file/temp/disk quotas and interruption-safe stop journal.', 'Independent predicate/checker implementation must be tested on synthetic fixtures before map search; reject cache/source disagreement as technical, never widen a tolerance.'],
      decisions=dict(success='Exactly one returned path passes independent original source geometry gate plus continuous tube certificate. Publish geometry-candidate status and a separate executor-compatibility status; do not promote speed/tracking/native/pixel or claim safety beyond these geometric predicates.',finite_reject='Completed exhaustive DP has no goal: this fixed conservative lattice method is insufficient on this exposed map. This is not nonexistence in the original tolerance-allowed graph, another grid, continuous path space or physical simulator.',compatibility_failure='Graph path is geometry-qualified but nonlocal/schema check fails: executor compatibility not qualified. No alternative-goal retry; do not label the entire graph/continuous geometry infeasible.',inconclusive='Partial search due CPU/RSS/disk/work/file/deadline cap, missing input, numerical/schema/source disagreement or interrupted audit. Preserve charged work and stop; no resolution/representation/cap change or retry.',no_auto_followup=True),
      privacy='Coordinates, seed, condition identity, masks/path/raw and private documents remain private. Publish method, fixed counts, aggregate result and source code only.',
      source_sha256={str(p.relative_to(G)):sha(p) for p in source_paths},source_function_AST_sha256={name:hashlib.sha256(ast.dump(funcs[name],include_attributes=False).encode()).hexdigest() for name in ('geometry','basis','obstacle_clearance','curvature','profile')})
    save(G/'retry/corridor488_contract.json',contract)
    save(d/'design-private.json',dict(stage=488,at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),code_sha256=sha(__file__),contract_sha256=sha(G/'retry/corridor488_contract.json'),input_paths_sha256={str(snapshot):sha(snapshot),str(baseline):sha(baseline)},new_grid_search_candidate_profile_physics_seed=0,CPU_s=time.process_time(),wall_s=time.perf_counter()-START,environment_read_command_check='Same environment pwd/git/file reads succeeded after disconnection alert; no environment transition.'))
    print(json.dumps(dict(stage=488,status=contract['status'],stored_dimensions=contract['counts_observed_map'],new_search=0,new_grid_states=0,new_profiles=0,new_physics=0,CPU_s=time.process_time(),wall_s=time.perf_counter()-START)))

if __name__=='__main__':run(Path(sys.argv[1]))
